//! Exercises items generated by a macro from another crate.
//!
//! `Counter` and `Counter::incr` are local to this crate, but charon reports
//! their spans as pointing into `macrolib/src/lib.rs`, so they go into the
//! `ExternalMacros` module.

macrolib::define_counter!(Counter);

pub fn make() -> Counter {
    Counter { value: 0 }
}
